// Insert the links RecordBus in the database.
// It is a no-op if 'items' is empty.
func InsertManyRecordBuss(tx *sql.Tx, items ...RecordBus) error {
	if len(items) == 0 {
		return nil
	}

	stmt, err := tx.Prepare(pq.CopyIn("record_buss",
		"idcompta",
		"idsubrecord",
	))
	if err != nil {
		return err
	}

	for _, item := range items {
		_, err = stmt.Exec(item.IdCompta, item.IdSubrecord)
		if err != nil {
			return err
		}
	}

	if _, err = stmt.Exec(); err != nil {
		return err
	}

	if err = stmt.Close(); err != nil {
		return err
	}
	return nil
}

