func loadJSON(out interface{}, src interface{}) error {
	if src == nil {
		return nil // zero value out
	}
	bs, ok := src.([]byte)
	if !ok {
		return errors.New("not a []byte")
	}
	return json.Unmarshal(bs, out)
}

func dumpJSON(s interface{}) (driver.Value, error) {
	b, err := json.Marshal(s)
	if err != nil {
		return nil, err
	}
	return driver.Value(string(b)), nil
}

func (s *CarsKms) Scan(src interface{}) error {
	var tmp pq.Int32Array
	err := tmp.Scan(src)
	if err != nil {
		return err
	}
	if len(tmp) != 3 {
		return fmt.Errorf("unexpected length %d", len(tmp))
	}
	copy(s[:], tmp)
	return nil
}

func (s CarsKms) Value() (driver.Value, error) {
	return pq.Int32Array(s[:]).Value()
}

func (s *MealsCount) Scan(src interface{}) error {
	var tmp pq.Int32Array
	err := tmp.Scan(src)
	if err != nil {
		return err
	}
	if len(tmp) != 5 {
		return fmt.Errorf("unexpected length %d", len(tmp))
	}
	copy(s[:], tmp)
	return nil
}

func (s MealsCount) Value() (driver.Value, error) {
	return pq.Int32Array(s[:]).Value()
}

func (s *Date) Scan(src interface{}) error {
	var tmp sql.NullTime
	err := tmp.Scan(src)
	if err != nil {
		return err
	}
	*s = NewDateFrom(tmp.Time)
	return nil
}

func (s Date) Value() (driver.Value, error) {
	return sql.NullTime{Time: s.Time(), Valid: true}.Value()
}

