func (s *OptionnalIdFilecompta) Scan(src interface{}) error {
	var tmp sql.NullInt64
	err := tmp.Scan(src)
	if err != nil {
		return err
	}
	*s = OptionnalIdFilecompta{
		Valid: tmp.Valid,
		Id:    IdFilecompta(tmp.Int64),
	}
	return nil
}

func (s OptionnalIdFilecompta) Value() (driver.Value, error) {
	return sql.NullInt64{
		Int64: int64(s.Id),
		Valid: s.Valid,
	}.Value()
}
